window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d03_otr10"]={"title": "991-ТО", "pages": 56, "pagesTxt": ["[стр. 1]\n2022 \n  \n \nВЫПОЛНЕНИЕ КОМПЛЕКСНОГО АНАЛИЗА С ОЦЕНКОЙ \nПРОЧНОСТИ, УСТОЙЧИВОСТИ И ЭКСПЛУАТАЦИОННОЙ \nНАДЕЖНОСТИ ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЙ \nСИСТЕМЫ ВЫСОКОНАПОРНОГО ГИДРОТРАНСПОРТА \nТАЛНАХСКОЙ ОБОГАТИТЕЛЬНОЙ ФАБРИКИ \nЗАПОЛЯРНОГО ФИЛИАЛА \nПУБЛИЧНОГО АКЦИОНЕРНОГО ОБЩЕСТВА  \n«ГОРНО-МЕТАЛЛУРГИЧЕСКОЙ КОМПАНИИ \n«НОРИЛЬСКИЙ НИКЕЛЬ» \nОбследование гидротехнических сооружений \nТехнический отчёт \n991-ТО", "[стр. 2]\n", "[стр. 3]\n", "[стр. 4]\nОбследование гидротехнических сооружений \n \n3 \n \nСОДЕРЖАНИЕ \nСостав отчетной документации ......................................................................... 5 \nТермины и определения ..................................................................................... 6 \nВведение .............................................................................................................. 8 \n1 Общая информация ...................................................................................... 9 \n1.1 Полное и сокращённое наименование объекта обследования .................... 9 \n1.2 Адрес (местоположение) объекта ................................ ................................ .. 9 \n1.3 Форма собственности ................................ ................................ ...................... 9 \n1.4 Сведения о собственнике ГТС ................................ ................................ ........ 9 \n1.5 Сведения об эксплуатирующей организации ................................ ................ 9 \n1.6 Сведения о Заказчике ................................ ................................ ................... 10 \n1.7 Сведения об исполнителе обследования ................................ .................... 10 \n1.8 Время проведения обследования ................................ ................................  10 \n1.9 Сведения о приборном оснащении, применяемом при \nобследовании ................................ ................................ ................................  10 \n1.10 Сведения о разработчике проекта ................................ ........................... 10 \n1.11 Сведения о Застройщике ................................ ................................ ......... 11 \n1.12 Сроки ввода объекта в эксплуатацию ................................ ..................... 11 \n1.13 Перечень технической документации, использованной при \nобследовании ................................ ................................ ................................  11 \n1.13.1 Проектная документация ................................ ................................ ..... 11 \n1.13.2 Эксплуатационная документация ................................ ........................ 11 \n2 Сведения об объекте, технологических и конструктивных \nрешениях, природных условиях................................................................. 13 \n2.1 Сведения о природных условиях района размещения объекта \nобследования ................................ ................................ ................................  13 \n2.1.1 Гидрографическая ................................ ................................ ................ 13 \n2.1.2 Климат ................................ ................................ ................................ .. 13 \n2.1.3 Топографические условия ................................ ................................ ... 14 \n2.1.4 Инженерно-геологические условия ................................ ..................... 14 \n2.1.5 Гидрогеологические условия ................................ ...............................  14 \n2.1.6 Геокриологические условия ................................ ................................ . 14 \n2.1.7 Сейсмические условия ................................ ................................ ......... 15 \n2.2 Сведения о технологических решениях по объекту \nобследования ................................ ................................ ................................  15 \n2.3 Сведения об объёмно-планировочных и конструктивных \nрешениях гидротехнических сооружений (ГТС) объекта ............................ 16 \n2.3.1 ПНС-1 ................................ ................................ ................................ .... 16 \n2.3.2 ПНС-2 ................................ ................................ ................................ .... 16 \n2.3.3 Высоконапорные трубопроводы ................................ .......................... 16 \n2.3.4 Класс ГТС ................................ ................................ ............................. 17 \n2.3.5 Конструктивные особенности ГТС ................................ ....................... 17 \n3 Результаты обследования ......................................................................... 18 \n3.1 Сооружения ................................ ................................ ................................ ... 18", "[стр. 5]\nОбследование гидротехнических сооружений \n \n4 \n \n3.1.1 ПНС-1 ................................ ................................ ................................ .... 18 \n3.1.2 ПНС-2 ................................ ................................ ................................ .... 18 \n3.1.3 Высоконапорные трубопроводы ................................ .......................... 18 \n3.1.4 Заключение по результатам визуального обследования .................. 38 \n3.2 Оценка соответствия критериям безопасности ГТС ................................ ... 39 \n3.3 Результаты поверочных расчётов ................................ ................................  41 \n3.3.1 Методика расчета ................................ ................................ ................ 41 \n3.3.2 Исходные данные ................................ ................................ ................. 42 \n3.3.3 Расчет трубы из условия на прочность ................................ ............... 43 \n3.3.4 Расчёт трубы из условия на жесткость ................................ ............... 44 \n3.3.5 Заключение по результатам расчетов ................................ ................ 45 \n3.4 Рассмотрение эксплуатационной документации ................................ ......... 46 \n4 Заключение ................................................................................................. 48 \nСписок литературы ........................................................................................... 50 \nПриложение А Техническое задание ............................................................... 51 \nПриложение Б Схема системы высоконапорного гидротранспорта \nТОФ-НМЗ ..................................................................................................... 55", "[стр. 6]\nОбследование гидротехнических сооружений \n \n5 \n \nСОСТАВ ОТЧЕТНОЙ ДОКУМЕНТАЦИИ \nНомер \nтома Обозначение Наименование Примечание \n  \nВыполнение комплексного анализа с оценкой \nпрочности, устойчивости и эксплуатационной \nнадежности гидротехнических сооружений системы \nвысоконапорного гидротранспорта Талнахской \nобогатительной фабрики Заполярного филиала \nпубличного акционерного общества «Горно-\nметаллургической компании «Норильский никель» \n \n 991-ТО.1 \n \nОбследование гидротехнических сооружений. \nТехнический отчёт", "[стр. 7]\nОбследование гидротехнических сооружений \n \n6 \n \nТЕРМИНЫ И ОПРЕДЕЛЕНИЯ \nВ отчёте использован ы термины и определения по ГОСТ 31937-2011, ГОСТ Р 22.2.09 -\n2015, ГОСТ 27751-2014. \nТехническое состояние гидротехнических сооружений \nПри оценке состояния ГТС принята следующая классификация ГОСТ 31937-2011: \nНормативное техническое состояние: Категория технического состояния, при котором \nколичественные и качественные значения параметров всех критериев оценки технического \nсостояния строительных конструкций зданий и сооружений, вкл ючая состояние грунтов \nоснования, соответствуют установленным в проектной документаци и значениям с учё том \nпределов их изменения. \nРаботоспособное техническое состояние:  Категория технического состояния, при \nкоторой некоторые из числа оцениваемых контролируе мых параметров не отвечают \nтребованиям проекта или норм, но имеющиеся нарушения требований в конкретных условиях \nэксплуатации не приводят к нарушению работоспособности, и необходимая несущая \nспособность конструкций и грунтов основания с учётом влияния имею щихся дефектов и \nповреждений обеспечивается. \nОграниченно-работоспособное техническое состояние:  Категория технического \nсостояния строительной конструкции или здания и сооружения в целом, включая состояние \nгрунтов основания, при которой имеются крены, дефекты и повреждения, приведшие к снижению \nнесущей способности, но отсутствует опасность внезапного разрушения, потери устойчивости \nили опрокидывания, и функционирование конструкций и эксплуатация здания или сооружения \nвозможны либо при контроле (мониторинге) технического состояния, либо при проведении \nнеобходимых мероприятий по восстановлению или усилению конструкций и (или) грунтов \nоснования и последующем мониторинге технического состояния (при необходимости). \nАварийное состояние: Категория технического состо яния строительной конструкции \nили здания и сооружения в целом, включая состояние грунтов основания, характеризующаяся \nповреждениями и деформациями, свидетельствующими об исчерпании несущей способности и \nопасности обрушения и (или) характеризующаяся кренами , которые могут вызвать потерю \nустойчивости объекта. \nУровни безопасности гидротехнического сооружения: \nКлассификация уровня безопасности принята по ГОСТ Р 22.2.09-2015. \nНормальный уровень безопасности  - Сооружение удовлетворяет всем проектным \nтребованиям по назначению и конструктивной надёжности, а также современным нормативным \nтребованиям; эксплуатация осуществляется в соответствии с действующими законодательными \nактами, нормами и правилами. Дальнейшая эксплуатация сооружений и оборудования возможна \nбез пр оведения каких -либо технических или организационных мероприятий по повышению \nбезопасности при обеспечении мониторинга безопасности и своевременном выполнении \nплановых ремонтно-профилактических работ. \nПониженный уровень безопасности ) - Имеются те или иные о тклонения от правил \nбезопасной эксплуатации, не устранённые своевременно в ходе плановых мероприятий по \nобеспечению нормального уровня безопасности, которые, однако, не препятствуют возможности \nвыполнения сооружением заданных эксплуатационных функций. Даль нейшая безопасная \nэксплуатация сооружения в проектном режиме возможна при обязательном выполнении в \nсогласованные (установленные) органами государственного надзора сроки мероприятий по \nповышению уровня безопасности, конкретный перечень которых вытекает из анализа факторов, \nобусловливающих максимальные значения показателей опасности и уязвимости. \nНеудовлетворительный уровень безопасности – Имеются отклонения от проектного \nсостояния и нарушения правил безопасной эксплуатации, которые могут привести к", "[стр. 8]\nОбследование гидротехнических сооружений \n \n7 \n \nвозникновению аварийной ситуации. Дальнейшая эксплуатация сооружения в проектном \nрежиме недопустима без проведения в установленные органами государственного надзора \nсроки тех или иных технических (вплоть до капитального ремонта, замены оборудования и др.) \nи организационных мероприятий по снижению риска аварий и восстановлению нормального \nуровня безопасности на основе анализа факторов, обусловливающих максимальные значения \nпоказателей опасности и уязвимости. К проведению такого анализа и разработке мероприят ий \nпо повышению уровня безопасности, как правило, должны привлекаться специализированные \nнаучно- исследовательские и проектные организации; в случае необходимости по специальным \nпрограммам предусматриваются полевые исследования физико -механических характер истик \nгрунтовых материалов, бетонных конструкций, проводятся дополнительные расчёты \nобоснования прочности и устойчивости сооружений и конструкций, корректируются ПДЗ \nконтролируемых параметров состояния и пр. \nОпасный (критический) уровень безопасности  – свидетельствуют об аварийной \nситуации, уровень безопасности ГТС оценивается как критический или опасный. В этом случае \nдальнейшая эксплуатация сооружения в проектном режиме по условиям риска аварии \nнедопустима и должна осуществляться в соответствии с тр ебованиями Постановления \nПравительства РФ от 27 февраля 1999 г. №237 «Об утверждении Положения об эксплуатации \nгидротехнического сооружения и обеспечении безопасности гидротехнического сооружения, \nразрешение на строительство и эксплуатацию которого аннулир овано (в том числе \nгидротехнического сооружения, находящегося в аварийном состоянии), гидротехнического \nсооружения, которое не имеет собственника или собственник которого неизвестен либо от права \nсобственности на которое собственник отказался». Необходимо незамедлительно \nинформировать органы государственного надзора и в соответствии с полученным \nпредписанием, ввести ограничения на режим эксплуатации (снижение уровня верхнего бьефа и \nдр.), разработать и утвердить временные правила эксплуатации. Мероприятия п о \nвосстановлению нормального уровня безопасности должны выполняться на основании анализа \nфакторов, обусловливающих возникновение аварийной ситуации, с обязательным \nпривлечением специализированных организаций. После проведения необходимых мероприятий \nперевод сооружений вновь в проектный режим эксплуатации должен быть согласован с \nорганами государственного надзора за безопасностью ГТС.", "[стр. 9]\nОбследование гидротехнических сооружений \n \n8 \n \nВВЕДЕНИЕ \nРаботы по выполнению комплексного анализа с оценкой прочности, устойчивости и \nэксплуатационной надёжности гидротехнических сооружений системы высоконапорного \nгидротранспорта Талнахской обогатительной фабрики Заполярного филиала Публичного \nакционерного общества «Горно -металлургической компании «Норильский никель» выполнены \nспециалистами ООО «Институт Красноярскгидропроект» на основании договора № ЗФ 2 568/22 \nот 1 8.07.2022 г. между Заполярным филиалом Публичного акционерного общества  \n«Горно-металлургическая компания «Норильский Никель» и Обществом с ограниченной \nответственностью «Проектно -изыскательский институт Красноярскг идропроект» \n(ООО «Институт Красноярскгидропроект»). \nПо результатам обследования, анализа данных натурных наблюдений  и регулярных \nэксплуатационных обследований ГТС, анализа и систематизации проектной и эксплуатационной \nдокументации отражено фактическое состояние объекта на июль 2022 г. \nНа основе полученных данных выполнен расчётный анализ прочностных и жёсткостных \nхарактеристик системы трубопроводного транспорта и даны рекомендации по внесению \nизменений в эксплуатационную документацию объекта.", "[стр. 10]\nОбследование гидротехнических сооружений \n \n9 \n \n1 ОБЩАЯ ИНФОРМАЦИЯ \n1.1 Полное и сокращённое наименование объекта обследования \nСистема высоконапорного гидротранспорта Талнахской обогатительной фабрики \n(гидротранспорт ТОФ) Заполярного филиала Публичного акционерного общества «Горно -\nметаллургической компании «Норильский никель» (ЗФ ПАО «ГМК «Норильский никель»). \n1.2 Адрес (местоположение) объекта \nОбъект протяжённый (общая длина 30 км) , расположен: Российская Федерация, \nКрасноярский край, город Норильск: \n– начало (пульпонасосная станция №  1, трасса трубопроводов) - район Т алнах, \nТалнахская обогатительная фабрика (ТОФ), главный корпус ИФЦ; \n– продолжение (пульпонасосная станция № 2, трасса трубопроводов) – медный завод, \nВокзальная, 9; \n– окончание (трасса трубопроводов) – Надеждинский металлургический завод (НМЗ). \n1.3 Форма собственности \nЧастная. \n1.4 Сведения о собственнике ГТС \nПолное наименование: Заполярный филиал Публичн ое акционерное общество «Горно -\nметаллургическая компания «Норильский никель».  \nСокращённое наименование: ЗФ ПАО «ГМК «Норильский никель». \nРуководитель: Директор, Уткин Николай Николаевич. \nЮридический адрес: Российская Федерация, 647000, Красноярский край, Таймырский \nДолгано-Ненецкий район, г. Дудинка, ул. Морозова, д. 1. \nПочтовый адрес: 663302, Российская Федерация, Красноярский край, г. Норильск, \nпл. Гвардейская, д. 2. \nТелефон: 8 (3919) 25-41-31, 25-41-55. \nЭлектронная почта: po_rprkirm@nornik.ru. \n1.5 Сведения об эксплуатирующей организации \nПолное наименование: Заполярный филиал Публичн ое акционерное общество «Горно -\nметаллургическая компания «Норильский никель».  \nСокращённое наименование: ЗФ ПАО «ГМК «Норильский никель». \nРуководитель: Директор, Уткин Николай Николаевич. \nЮридический адрес: Рос сийская Федерация, 647000, Красноярский край, Таймырский \nДолгано-Ненецкий район, г. Дудинка, ул. Морозова, д. 1. \nПочтовый адрес: 663302, Российская Федерация, Красноярский край, г. Норильск, \nпл. Гвардейская, д. 2. \nТелефон: 8 (3919) 25-41-31, 25-41-55.", "[стр. 11]\nОбследование гидротехнических сооружений \n \n10 \n \nЭлектронная почта: po_rprkirm@nornik.ru. \n1.6 Сведения о Заказчике \nПолное наименование: Заполярный филиал Публичн ое акционерное общество «Горно -\nметаллургическая компания «Норильский никель».  \nСокращённое наименование: ЗФ ПАО «ГМК «Норильский никель». \nРуководитель: Директор, Уткин Николай Николаевич. \nЮридический адрес: Российская Федерация, 647000, Красноярский край, Таймырский \nДолгано-Ненецкий район, г. Дудинка, ул. Морозова, д. 1. \nПочтовый адрес: 663302, Российская Федера ция, Красноярский край, г. Норильск, \nпл. Гвардейская, д. 2. \nТелефон: 8 (3919) 25-41-31, 25-41-55. \nЭлектронная почта: po_rprkirm@nornik.ru. \n1.7 Сведения об исполнителе обследования \nПолное наименование организации: Общ ество с ограниченной ответственностью \n«Проектно-изыскательский институт Красноярскгидропроект». \nСокращённое наименование организации: ООО «Институт Красноярскгидропроект». \nМестонахождение организации: (индекс, регион, город) РФ, Красноярский край, \n660075, г. Красноярск, ул. Маерчака,8, стр. №2, пом.9, оф.227. \nФактический адрес организации: РФ, Красноярский край, 660075, г. Красноярск, \nул. Маерчака,8, стр. №2, пом.9, оф.227. \nРуководитель организации: Генеральный директор ООО «Институт \nКрасноярскгидропроект», действующий на основании Устава, Вайкум Владимир Андреевич \nТелефон * (391)204 12 84; (923)2887993, (983)2054188. \nЭлектронная почта kgp24@yandex.ru \n1.8 Время проведения обследования \nПолевые работы по визуальному обследованию выполнялись с 19 по 20.07.2022  г. \nАнализ эксплуатационной документации, проведение поверочных расчетов и составление \nотчета выполнены с 25.07.2022г по 08.09.2022г. \n1.9 Сведения о приборном оснащении, применяемом при \nобследовании \n1 Наковальня поверочная ОН-2 №214; \n2 Склерометр ОМШ-1 №773; \n3 Ультразвуковой толщиномер Cygnus 1; \n4 Рулетка; \n5 Фотоаппарат. \n1.10 Сведения о разработчике проекта \nПроект разработан:", "[стр. 12]\nОбследование гидротехнических сооружений \n \n11 \n \n«Всесоюзный ордена Трудового Красного Знамени научно -исследовательский и \nпроектный институт «Механобр». \nПравопреемник: \nАкционерное общество «Механобр инжиниринг» зарегистрировано 13 декабря 1990 года \nи является правопреемником прав и обязанностей проектной и научной частей государственного \nпредприятия «Всесоюзный ордена Трудового Красного Знамени научно -исследовательский и \nпроектный институт «Механобр». \nПолное наименование: \nАкционерное общество «Механобр инжиниринг». \nСокращенное наименование: \nАО «Механобр инжиниринг». \nЮридический адрес: \n199106, город Санкт-Петербург, линия 22-я В.О., дом 3 корпус 7 литер к, офис 204. \nТелефон:8-812-324-89-24. \nФакс: 8-812-321-37-70. \nИНН: 7801004257. \nКПП: 780101001. \n1.11 Сведения о Застройщике \nДанные о строительной организации отсутствуют. \n1.12 Сроки ввода объекта в эксплуатацию \nВвод в постоянную эксплуатацию – 1979 г. \n1.13 Перечень технической документации, использованной при \nобследовании \n1.13.1 Проектная документация \nИз проектной документации для гидротранспорта Талнахской обогатительной фабрики \nЗФ ПАО «ГМК «Норильский никель» имеется: \n– Проект 20226. Норильский ордена Ленина Горно-металлургический комб инат \nим. А. П. Завенягина. Расширение и реконструкция. Обогатительная фабрика №2; \n– Проект ОФ -2-22. ОФ -2. Мостовой переход трассы гидротранспорта продуктов \nобогащения через реку Норильскую; \n– Проект 320875-КЖ. ОФ-2. Поддержание мощностей в связи с изменением к ачества \nсырья. Установка насосов «ГЕХО»; \n– Проект 3494.1-ИОС7.2 Реконструкция и техническое перевооружение с увеличением \nмощности до 16 млн. т. в год по сумме руд. \n1.13.2 Эксплуатационная документация \nЗаказчиком предоставлена следующая документация:", "[стр. 13]\nОбследование гидротехнических сооружений \n \n12 \n \n– Правила эксплуа тации гидротехнических сооружений системы высоконапорного \nгидротранспорта Талнахской обогатительной фабрики г. Норильск, 2022. \n– Декларация безопасности гидротехнических сооружений системы высоконапорного \nгидротранспорта Талнахской обогатительной фабрики ЗФ ПАО «ГМК «Норильский \nникель». г. Норильск, 2021. \n– Акт регулярного обследования ГТС системы высоконапорного гидротранспорта \nТалнахской обогатительной фабрики ЗФ ПАО «ГМК «Норильский никель». Норильск, \n2021. \n– Расчёт вероятного вреда, который может быть причинён жизни, здоровью физических \nлиц, имуществу физических и юридических лиц в результате аварии \nгидротехнических сооружений высоконапорного гидротранспорта Талнахской \nобогатительной фабрики ЗФ ПАО «ГМК «Норильский никель», 2020 год. \n– Критерии безопасности гидр отехнических сооружений системы высоконапорного \nгидротранспорта Талнахской обогатительной фабрики ЗФ ПАО «ГМК «Норильский \nникель», 2021 год. \n– Заключение экспертной комиссии на декларацию безопасности ГТС высоконапорного \nгидротранспорта Талнахской ОФ ЗФ ПАО «ГМК «Норильский никель». \nРегистрационный номер 00-ДБ-0198-2021. \n– Порядок эксплуатации гидротехнических сооружений и гидротранспорта Талнахской \nобогатительной фабрики ЗФ ПАО ГМК Норильский никель от 26.11.2018 г. \n– Проект мониторинга безопасности ГТС системы высоконапорного гидротранспорта \nТалнахской обогатительной фабрики ЗФ ПАО ГМК Норильский никель от 10.01.2022 г. \n– Акт о выполненном обследовании технического состояния ГТС хвостохранилища \nТОФ от 10.06.2022, ЗФ-39-02-03/066-акт. \n– Акт о выполненном обследовании технического состояния системы высоконапорного \nгидротранспорта ТОФ от 23.06.2022, ЗФ-39-02-03/76-акт. \n– Акт о выполненном предпаводковом обследовании ГТС системы высоконапорного \nгидротранспорта ТОФ от 20.05.2022, № ЗФ-71/032-акт. \n– Акт о выполненном послепаво дковом обследовании ГТС системы высоконапорного \nгидротранспорта ТОФ от 17.06.2022, № ЗФ-71/045-акт.", "[стр. 14]\nОбследование гидротехнических сооружений \n \n13 \n \n2 СВЕДЕНИЯ ОБ ОБЪЕКТЕ,  ТЕХНОЛОГИЧЕСКИХ И \nКОНСТРУКТИВНЫХ РЕШЕНИЯХ, ПРИРОДНЫХ УСЛОВИЯХ \n2.1 Сведения о природных условиях района размещения объекта \nобследования \nРайон расположения объекта растянут на 30 км от ТОФ в районе Талнах, расположенного \nв 20 км от Норильска и до НМЗ. \n2.1.1 Гидрографическая \nГидрографическая сеть района, в основном, принадлежит к бассейну оз.  Пясино. \nОсновными водными артериями района являются р. Норильская, соединяющая оз.  Мелкое, \nнаходящееся восточнее описываемой территории и оз. Пясино, а также р. Рыбная, вытекающая \nиз оз. Кета, расположенного в 80 км юго-восточнее г. Норильска и впадающая в р. Норильскую в \n35 км от ее устья. Реки второго пор ядка - Ергалах, Талнах, Хараелах, Валек, Листвянка, \nАмбарная и другие впадают в указанные реки или непосредственно в оз. Пясино. \n2.1.2 Климат \nКлимат района субарктический, характеризуется отрицательной среднегодовой \nтемпературой воздуха, продолжительной зимой с сильными морозами и метелями, холодным и \nдождливым летом. \nСреднемесячная (среднемноголетняя) температура воздуха с октября по май \nотрицательная и равна –18,5ºС. В течение пяти месяцев она ниже – 20ºС, с июня по сентябрь \nвыше 0ºС с максимумом (32,2ºС). \nПервые устойчивые морозы наступают 2 октября и заканчиваются 1 июня. \nПродолжительность периода с положительной среднесуточной температурой воздуха \nсоставляет 117 дней; продолжительность периода с отрицательной температурой воздуха 248 \nдней. \nАбсолютный максимум  температуры воздуха +32,2ºС, абсолютный минимум — 56ºС. \nГодовая амплитуда колебания температур около 90ºС. \nСреднегодовая (многолетняя) температура воздуха — 9,5ºС. \nАбсолютная влажность изменяется от 0,7 мб в январе до 10,6 мб июле. \nСреднегодовая абсолютна я влажность — 3,92 мб, относительная — 76%; дефицит \nвлажности — 1,5 мб. \nГодовая сумма осадков 479 мм. Суточный максимум осадков приходится на август — \n44,2 мм. Число дней с осадками изменяется от 143 до 195. \nОбеспеченность суточных осадков распределяется следующим образом: 0,1% — 120 мм; \n0,5% — 98 мм; 1% — 75 мм; 2% — 65 мм; 5% — 42 мм; 10% — 36 мм. \nСнежный покров устанавливается в третьей декаде сентября и исчезает в первой \nполовине июня. Число дней со снежным покровом — 244. Плотность снега перед снеготаянием \nв среднем 0,3 г/см³. \nВысота снежного покрова в районе Талнаха составляет: на закрытых участках — 2,5 м, \nна открытых участках — 0,2-0,6 м. \nМаксимальная скорость ветра достигает 30 м/сек. Число дней в году с гололедом 5÷32, с \nизморозью 35÷132.", "[стр. 15]\nОбследование гидротехнических сооружений \n \n14 \n \n2.1.3 Топографические условия \nНорильский промышленный район имеет площадь около 60 тыс. км 2 и расположен к \nвостоку от р.  Енисей между 86 -92º восточной долготы и 68 -70º северной широты в северо -\nзападной части Среднесибирского плоскогорья г.  Норильск, находится в 90 км к востоку от \nг. Дудинки и связанный с ним железной и шоссейной дорогами. \nНорильский район приурочен к северо -западной, так называемой Северо -Сибирской \nникеленосной металлогенической оконечности Сибирской платформы. \nРельеф участка представляет собой а ллювиально-делювиальную равнину, частично \nзаболоченную, с большим количеством озёр, соединённых протоками, переходящими в ручьи. \nПоверхность представляет обширную низкую холмисто – увалистую равнину со средними \nвысотами 60 м над уровнем моря, с разнообразн ым и сложным рельефом и повсеместно \nраспространенными мерзлотными формами. \n2.1.4 Инженерно-геологические условия \nНа участке трассы высоконапорного гидротранспорта  в геологическом строении разрез \nчетвертичных отложений представлен нерасчлененными аллювиально-озерными отложениями \nвальковской и арылахской толщ и гляциальными отложениями наледнинской толщи. Отложения \nчетвертичной системы подстилаются скальными грунтами пермской свиты. \nАллювиально-озерные отложения (al QIII-IV) развиты повсеместно и залегают с дневной \nповерхности до глубины 25,0 и более метров. Представлены в основном суглинками, \nпереслаивающимися с супесями и прослоями песка мелкого. В мерзлом состоянии суглинки и \nсупеси льдистые и сильнольдистые с линзами и прослоями льда, редко слабольдистые. В талом \nсостоянии суглинки от текучих до мягкопластичных. На пересечениях с ручьями в верхней части \nразреза встречаются прослои гравия и песков разнозернистых. \nГляциальные отложения (g  QIII), относящиеся к эпохе оледенения, представлены \nгравийно-галечниковыми грунтами и плотными суглинками с галькой и валунами. Ледниковые \nотложения вскрыты с глубины 8,0 метров и глубже.  \nК современным образованиям относятся биоге нные отложения (b  QIV) и техногенные \nобразования (t QIV). \nОрганические отложения на начальном участке трассы, от ТОФ до р.Норильская  \nраспространены повсеместно . На участке от р.Норильская до НМЗ органические отложения \nвстречаются только в понижениях рельефа и вблизи котловин озер.  \n2.1.5 Гидрогеологические условия \nГидрогеологические условия участка характеризовались наличием надмерзлотных \nподземных вод, функционирующих в слое сезонного оттаивания в летне -осенний период. \nПитание водоносного горизонта осуществляется за счет инфильтрации атмосферных осадков и \nвод весеннего снеготаяния. При этом уровень подземных вод может достигать поверхности \nрельефа, что способствует заболачиванию пониженных территорий. \nВ тёплый период года, во время интенсивных дождей и снеготаяни я, вдоль трассы \nнаблюдается появление грунтовых вод типа «верховодка».  \n2.1.6 Геокриологические условия \nТерритория Норильского промышленного района относится к Енисей -Путоранскому \nгеокриологическому региону. Территория района расположена в пределах геокриологиче ских \nобластей плато Норильского и Норильско -Рыбнинской межгорной равнины. В пределах \nНорильского плато (горная и предгорная части описываемой территории) мощность \nмноголетнемерзлых пород изменяется в зависимости от абсолютных отметок рельефа и \nсоставляет до 100 метров и более. В границах Норильско -Рыбнинской равнины  мощность \nмноголетнемерзлых пород изменяется в зависимости от  абсолютных отметок рельефа,", "[стр. 16]\nОбследование гидротехнических сооружений \n \n15 \n \nсоставляя в поймах рек 15 - 20 метров, а в пределах распространения ледово-морских и озерных \nтеррас - до 50 метров. На предсклоновых участках территории мощность многолетнемерзлых  \nпород увеличивается до 100 метров. По способу промерзания горных пород  мерзлая толща \nотносится к эпигенетическому типу. \n2.1.7 Сейсмические условия \nПлощадка в соответствии с СП 14.13330.2018 относится к зоне с сейсмичностью 5 баллов. \n2.2 Сведения о технологических решениях по объекту обследования \nСистема высоконапорного гидротранспорта состоит из пульпонасосной станции  №1 \n(ПНС˗1), расположенной в главном корпусе ИФЦ ТОФ, пульпонасо сной станции №2 (ПНС˗2), \nрасположенной в 20 км от ТОФ на площадке медного завода , и трассы трубопроводов от ТОФ \nдо НМЗ общей протяженностью 30 км. \nВ пульпонасосной станции № 1 установлено 17 насосов Гехо TZPM 1600 (Нидерланды), \nпроизводительностью 250-400 м3/час и напором до 800 м.вод.ст. \nВ пульпонасосной станции №  2 установлено 10 насосов: 8 насосов 9х9 v7 фирмы \nИнгерсол Рэнд и 2 насоса Гехо TPZM 1600 производительностью 250 -400 м 3/час и напором \nдо 800 м.вод.ст. \nСогласно приказу федеральной службы по экологическому, технологическому и атомному \nнадзору от 07.12.2020 г. №499 «Об утверждении формы представления сведений о \nгидротехническом сооружении, необходимых для формирования и ведения Российского \nрегистра гидротехнических сооружений» определены вид и тип ГТ С системы высоконапорного \nгидротранспорта, данные сведены в Таблица 2.1. \nТаблица 2.1 – Вид и тип ГТС системы высоконапорного гидротранспорта  \nВид Наименование Тип Наименование Конкретный состав ГТС \n6 ГТС специального \nназначения 4 Насосные станции Пульпонасосная станция №1 (ПНС-1) \nПульпонасосная станция №2 (ПНС-2) \n4 Водопроводящие ГТС 1 \nВодоводы, \nпульповоды, \nтуннели, лотки, \nзолошлакопроводы, \nакведуки \nВысоконапорные трубопроводы от \nТОФ до НМЗ \nМаксимальная проектная производительность ПНС-1 – 1,88 м3/с, ПНС-2 – 1,11 м3/с. \nСистема высоконапорного гидротранспорта предназначена для транспортировки \nпродуктов обогащения и воды: \nМедный концентрат ТОФ поступает на участок фильтрации медного концентрата медного \nзавода. \nОт ПНС-1 до ПНС -2 смонтирована магистраль из девяти трубопроводов, на участке от \nПНС-2 до НМЗ смонтирована магистраль из восьми трубопроводов, от НМЗ смонтирована одна \nнитка трубопровода до ПНС-3. Нерабочие нитки трубопроводов на данных участках находятся в \nобщем резерве. \nНикелевый концентрат Норильской обогатительной фабрики (далее – НОФ) подают на \nНМЗ с подкачкой насосами ПНС-2 по отдельной нитке трубопроводов. \nТаким образом, с учетом возврата сливов сгустителей с НМЗ и МЗ на ТОФ на участке от \nПНС-1 до ПНС-2 задействованы 5 ниток трубопроводов (три нитки на концентратах и две нитки \nна сливах), на участке от ПНС -2 до НМЗ задействованы 5 ниток трубоп роводов (две нитки на \nNi˗концентрате, две нитки на сливах сгустителей).", "[стр. 17]\nОбследование гидротехнических сооружений \n \n16 \n \nКоличество одновременно задействованных трубопроводов, направление  подачи, тип \nперекачиваемого продукта могут изменяться в зависимости от режима работы технологических \nцепочек предприятий. \nВ соответствии с п.  8.21 СП  58.13330.2019 расчетные сроки службы основных \nгидротехнических сооружений в зависимости от их класса ответственности следует принимать \n(если иное не определено в задании на проектирование) равными:  для сооружений IV классов \nответственности - 50 лет. \nФактический срок эксплуатации ГТС ТОФ – НМЗ составляет 43 года. \n2.3 Сведения об объёмно-планировочных и конструктивных \nрешениях гидротехнических сооружений (ГТС) объекта \n2.3.1 ПНС-1 \nНасосная расположена в здании измельчительно-флотационного цеха (ИФЦ) ТОФ. Часть \nздания - однопролётная. Фундамент монолитный железобетонный столбчатый. Колонны  \nметаллические. В качестве несущих конструкции покрытия используются  стропильные балки, \nстеновые ограждения - золобетонные панели, кирпичная кладка. Длина составляет 216 метров, \nширина 30 метров, максимальная высота  здания 37,5 метров. В насосной имеется дренажный \nлоток, зумпфы для приёма перекачиваемого материала из ИФЦ. Здание предназначено для \nразмещения персонала, насосного о борудования, задействованного в нагнетании продуктов  \nобогащения в трубопроводы. В насосной установлены 17 насосных установок «ГЕХО». Насосная \nустановка состоит из мембранно-поршневого насоса «ГЕХО», насосов 8ПС10 или Warman для \nнагнетания перекачиваемого м атериала из  зумпфов ПНС-1 через наполняющие клапаны  в \nкорпус мембраны «ГЕХО», из  которого перекачиваемый материал подаётся под давлением в \nтрубопроводы, электродвигателя и редуктора для передачи крутящего момента на ведущий вал \nнасоса «ГЕХО». \n2.3.2 ПНС-2 \nНасосная расположена на промплощадке медного завода. Здание каркасное, \nдвухпролётное, одноэтажное в рядах В -Г, четырехэтажное в рядах А -Б. Фундамент - свайный \nростверк. Колонны – металлические. Несущие конструкции покрытия – стальные фермы. \nСтеновое огражд ение – газозолобетонные панели, кирпичная кладка. Длина составляет \n180 метров, ширина 38  метров, максимальная высота 20,75  метров. В насосной имеется \nдренажный лоток. Здание предназначено для размещения персонала, насосного оборудования, \nзадействованного в нагнетании продуктов обогащения в трубопроводы. В насосной установлено \n2 насосных установ ки «ГЕХО» , аналогичных установкам ПНС -1, и 8 насосных установок \n«Ингерсолл-рэнд». Насосная установка «Ингерсолл -рэнд» типа 9v7 состоит из плунжерного \nнасоса, подкачивающих насосов, электродвигателя. Нагнетание перекачиваемого  материала \nосуществляется возвратно поступательными движениями плунжеров  «Ингерсолл-рэнд». \nПодкачивающие насосы 8ПС10 предназначены для нагнетания перекачиваемого материала из \nзумпфов ПНС -2 в «Инге рсолл-рэнд», из которого перекачиваемый материал подается под \nдавлением в  трубопроводы. Электродвигатель служит для передачи крутящего момента на  \nведущий вал насоса «Ингерсолл-рэнд». \n2.3.3 Высоконапорные трубопроводы \nПроложено 9 трубопроводов от ТОФ до ПНС -2, от  ПНС-2 до НМЗ 8 трубопроводов \nдиаметром 273 мм и толщиной стенки 10 мм. Длина трубопроводов 30 км. Трубопроводы \nметаллические, имеют внутренний защитный антикоррозионный слой покрытия из стекломассы, \nчто обеспечивает большую продолжительность срока службы трубопроводов, сокращает \nгидравлические потери, исключает отложение осадков на стенках труб, уменьшает вероятность \nзагрязнения окружающей среды.", "[стр. 18]\nОбследование гидротехнических сооружений \n \n17 \n \n2.3.4 Класс ГТС \nПроектом высоконапорного гидротранспорта Талнахской обогатительной фабрики класс \nГТС не назначен. \nКласс ГТС (в соответствии с Постановлением Правительства РФ от 05.10.2020 г № 1607 \n«О классификации гидротехнических сооружений») установлен как IV. \nКласс опасности отходов: V. \n2.3.5 Конструктивные особенности ГТС \nБольшая протяжённость трубопроводов.  \nНадземная про кладка трубопроводов - над уровнем земли на отдельных опорах и \nэстакадах различных конструкций на расстоянии от грунта , обеспечивающим установку \nтеплоизоляции. \nНаличие пересечений с водными объектами , транспортными магистралями и \nтехнологическими проездами.", "[стр. 19]\nОбследование гидротехнических сооружений \n \n18 \n \n3 РЕЗУЛЬТАТЫ ОБСЛЕДОВАНИЯ \n3.1 Сооружения \nВ ходе выполнения работы выполнены: \n– сбор исходной информации; \n– комплексное визуальное и инструментальное обследование ГТС; \n– оценка технического состояния ГТС; \n– разработка рекомендаций, направленных на обеспечение эксплуатационной \nнадёжности и безопасности гидротехнических сооружений гидротранспорта ТОФ. \n3.1.1 ПНС-1 \nВ 2020 году ООО «Безопасность в промышленности» была проведена экспертиза \nпромышленной безопасности здания измельчительно-флотационного цеха м/о «К-Л», м/р «1-37» \nТалнахской обогатительной фабрики (место расположения ПНС -1), и выдано заключение \n№765/2020-ЭПБ. \nПо результатам обследования сделаны следующие выводы. Фактическое техническое \nсостояние строительных ко нструкций здания в целом оценивается как ограниченно \nработоспособное. Остаточный ресурс строительных конструкций здания до аварийного \nсостояния составляет 21 год. \n3.1.2 ПНС-2 \nВ 2017 году Акционерным Обществом Научно –исследовательский центр «Горный \nЭксперт» была проведена экспертиза промышленной безопасности здания пульпонасосной \nстанции №2, и выдано заключение №057-17КР. \nСогласно РД 22-01-97 здание ПНС-2 было признано ограниченно работоспособным. Все \nконструкции с выявленными дефектами заменяемы или ремонтопригод ны. Аварийные \nэлементы здания заменены. \n3.1.3 Высоконапорные трубопроводы \nОсновное внимание при визуальном осмотре и натурном обследовании уделено \nвысоконапорным трубопроводам. \nСхема системы высоконапорного гидротранспорта ТОФ -НМЗ представлена в \nприложении Б. Осмотр трассы трубопроводов проходил по маршруту ПНС -1 (ТОФ) – ПНС-2 \n(медный завод) – НМЗ (Рисунок 3.1). \nВ конструктивном отношении на трассе используются следующие типы опор: \n– лежневые; \n– городковые; \n– высокие металлические, в том числе вантовой конструкции, опоры перехода через \nр. Норильская; \n– свайные (металлические и железобетонные) опоры с железобетонными траверсами; \n– неподвижные железобетонные опоры с металлическими боковы ми упорами и \nжелезобетонными вертикальными упорами; \n– неподвижные железобетонные опоры с железобетонными боковыми упорами.", "[стр. 20]\nОбследование гидротехнических сооружений \n \n19 \n \nОбщее состояние трассы \nТрасса несколько раз пересекает технологические проезды, автодороги, железную \nдорогу: ПК 4, ПК 8+50, ПК 106+50, ПК 132, ПК 178, ПК 196, ПК204, ПК219, ПК228 и др., проход \nчерез которые осуществляется в железобетонных лотках и металлических трубах-футлярах.  \nНа пересечениях с транспортами магистралями и технологическими проездами местами \nпроизошло осыпание грунта с от косов насыпи на трубы, трубы опустились на грунт, что \nисключает возможность установки теплоизоляции и создаёт дополнительное нерасчётное \nзащемление труб, в т.ч. при замерзании грунта и воды неорганизованного поверхностного стока: \nРисунок 3.2, Рисунок 3.25, Рисунок 3.26, Рисунок 4.24, Рисунок 3.35. Требуется расчистка труб.  \nВ районе хвостохранилища ТОФ, в месте прокладки трубопроводов под технологическим \nпроездом на ПК8+50, при замене теплоизоляции временно демонтированы две ж/б плиты \nпокрытия ( Рисунок 3.2). После установки теплоизоляции н еобходимо восстановить пок рытие \nтрассы. \nНа участке трассы, проходящем по Талнахскому району, вдоль и между трубами \nинтенсивно прорастает молодая поросль кустарников и деревьев ( Рисунок 3.6, Рисунок 3.11 и \nдр.). Мелкая растительность не отражается на работе трубопроводов. Крупной растительности \nвдоль трассы для обеспечения свободного доступа к трубам требует удаления.  \nЗдесь же (на участке ПК 40-ПК50) в отдельных местах в результате просадки опор \nобразовались провисы трубопроводов с пролётами длиной до 12м.  \nВ процессе обследования были произведены выборочные замеры толщины труб \n(Рисунок 3.21). В местах измерения толщина труб колеблется от 9.1 до 10 мм при критериальном \nзначении первого уровня К1=10мм, второго уровня К2=5мм.  \nЛежневые опоры \nБольшинство опор – лежневые и городкового типа. Многие лежневые опор ы за время \nэксплуатации потеряли свою функцию . Часть опор опустилась, в результате чего трубы \nпровисают (Рисунок 3.24). Такие участки требуют выправки трубопроводов подсыпкой балласта \nпод опоры (суфляж). Сгнившие опоры необходимо заменить (Рисунок 3.26). \nНа пониженных замкнутых бессточных участках для предотвращения вмерзания  труб в \nгрунт рекомендуется выполнить отвод поверхностного стока с трассы (Рисунок 3.27). \nГородковые опоры \nВ первой половине трассы, в местах пересечённой местности и высокого расположения \nтруб над землёй, используются городковые опоры. Часть опор требуют восстановления, \nремонта или замены.   \nНа рис. 3.9 городковая опора выгнулась и требует замены с увеличением общего \nпоперечного сечения. На рис. 3.13 представлена разрушенная городковая опора.  \nПри восстановлении городковых опор для более надёжней работы рекомендуется \nскреплять брусья опор строительными скобами (Рисунок 3.12, Рисунок 3.13). \nВ конце трассы , перед НМЗ , часть городковых опор тоже сдвинуто, опоры требуют \nвосстановления (Рисунок 3.38). \nВысокие металлические опоры \nВысокие металлические опоры в районе р. Норильская находятся в работоспособном \nсостоянии кроме одной ( Рисунок 3.17), на которой погнута стойка и нарушена вертикальная \nсвязь. Рядом, для разгрузки неработоспособной опоры, установлены городковые опоры.", "[стр. 21]\nОбследование гидротехнических сооружений \n \n20 \n \nСвайные опоры \nСвайные (металлические и железобетонные) о поры с железобетонными траверсами \n(Рисунок 3.5, Рисунок 3.19) также находятся в работоспособном состоянии.  \nИсключение составляют высокие свайные железобетонные опоры, подверженные \nдеградации бетона на пересечениях с водотоками в зоне переменного уровня воды. \nНеподвижные опоры \nНеподвижные опоры в основном находятся в нормативном т ехническом состоянии. При \nконтрольной проверке прочность бетона опор составила 24Мпа.  \nНа начальном наиболее заболоченном участке трассы до ПК100 службой эксплуатации \nвыявлена просадка и крен нескольких неподвижных опор. У одной неподвижной опоры сколоты \nбоковые железобетонные упоры. Запланировано восстановление опор. \n \n \nРисунок 3.1 –ПК6 - ПК8. Ремонтные работы.", "[стр. 22]\nОбследование гидротехнических сооружений \n \n21 \n \n \nРисунок 3.2 – ПК8+50. Технологический проезд. Демонтированы две ж/б плиты \nпокрытия \n \nРисунок 3.3 – ПК9. Неподвижная опора. Прочность бетона 24-26МПа. Минимальная \nтолщина стенки пульпопровода 9,9мм", "[стр. 23]\nОбследование гидротехнических сооружений \n \n22 \n \n \nРисунок 3.4 – ПК9. Общий вид трассы трубопроводов с компенсационными \nповоротами. Лежневые опоры. Дефектов нет. \n \n \nРисунок 3.5 – ПК11. Неподвижная опора.", "[стр. 24]\nОбследование гидротехнических сооружений \n \n23 \n \n \nРисунок 3.6 – ПК15. Общий вид трассы трубопроводов. Молодая поросль кустарника.", "[стр. 25]\nОбследование гидротехнических сооружений \n \n24 \n \n \nРисунок 3.7 – ПК19. Неподвижная опора.  \n \nРисунок 3.8 – ПК22. Ремонт теплоизоляции.", "[стр. 26]\nОбследование гидротехнических сооружений \n \n25 \n \n \nРисунок 3.9 – ПК27.Трасса трубопроводов по высоким городковым и железобетонной \nсвайной опорам.  \n \nРисунок 3.10 – ПК27. Трасса трубопроводов по высоким железобетонным свайным \nопорам", "[стр. 27]\nОбследование гидротехнических сооружений \n \n26 \n \n \nРисунок 3.11 – ПК52. Общий вид трассы трубопроводов. Молодая поросль. \n \nРисунок 3.12 – ПК 52. Городковые опоры.", "[стр. 28]\nОбследование гидротехнических сооружений \n \n27 \n \n \nРисунок 3.13 – ПК 52. Сход с опор второй левой нитки трубопровода \n \nРисунок 3.14 – ПК 101. Высокие опоры на ж/б сваях. Отсутствие теплоизоляции \n \nРисунок 3.15 – ПК 103. Высокие опоры на металлических сваях.", "[стр. 29]\nОбследование гидротехнических сооружений \n \n28 \n \n \nРисунок 3.16 – Эстакада  трубопроводов через р.Норильская. Усиление городковыми \nопорами. \n \nРисунок 3.17 – Эстакада  трубопроводов через р.Норильская. Усиление городковыми \nопорами (погнута стойка опоры, нарушена вертикальная связь опоры).", "[стр. 30]\nОбследование гидротехнических сооружений \n \n29 \n \n \nРисунок 3.18 –ПК121. Плановый ремонт теплоизоляции и опор. \n \n \nРисунок 3.19 – ПК125. Свайные металлические опоры с железобетонной траверсой.", "[стр. 31]\nОбследование гидротехнических сооружений \n \n30 \n \n \nРисунок 3.20 – ПК 147. Трасса трубопровода. Расчистка и восстановление \nтерритории, ремонт опор и теплоизоляции. \n \nРисунок 3.21 – ПК 147. Измерение толщины трубы (9.1мм).", "[стр. 32]\nОбследование гидротехнических сооружений \n \n31 \n \n \nРисунок 3.22 – ПК 150. Общий вид трассы. Ремонтные работы. \n \nРисунок 3.23 – ПК 168. Замена теплоизоляции.", "[стр. 33]\nОбследование гидротехнических сооружений \n \n32 \n \n \nРисунок 3.24 – ПК174. Отсутствие опирания на лежневую опору \n \n \nРисунок 3.25 – ПК 178. Прокладка трассы трубопровода под технологическим \nпроездом. Пересыпаны правые нитки.", "[стр. 34]\nОбследование гидротехнических сооружений \n \n33 \n \n \nРисунок 3.26 – ПК 242. Трасса трубопровода. Нарушена теплоизоляция. Трубы лежат \nна земле, присыпаны грунтом.  \n \nРисунок 3.27 – ПК 242. Проход трассы трубопроводов в трубах-футлярах. Нарушена \nтеплоизоляция.", "[стр. 35]\nОбследование гидротехнических сооружений \n \n34 \n \n \nРисунок 3.28 – ПК 242. Определение толщины стенки трубопровода (9,1мм). \n \nРисунок 3.29 – ПК 263 (37). Общий вид трассы. Дефектов нет \n \nРисунок 3.30 – ПК 263+50 (36+50). Переезд к насосной. Нарушена теплоизоляция.", "[стр. 36]\nОбследование гидротехнических сооружений \n \n35 \n \n \nРисунок 3.31 – ПК 267 (33). Переезд. Дефектов нет. \n \nРисунок 3.32 – ПК 269 (31). Неподвижная опора. Дефектов нет. \n \nРисунок 3.33 – ПК 269+50. Нарушена теплоизоляция.", "[стр. 37]\nОбследование гидротехнических сооружений \n \n36 \n \n \nРисунок 3.34 – ПК 277 (23). Неподвижная опора. Дефектов нет \n \nРисунок 3.35 – ПК 281 (19). На переезде засыпана левая нитка", "[стр. 38]\nОбследование гидротехнических сооружений \n \n37 \n \n \nРисунок 3.36 – ПК 291 (5). Общий вид трассы. Дефектов нет \n \nРисунок 3.37 – ПК 294 (2). Вход трассы на территорию НМЗ.", "[стр. 39]\nОбследование гидротехнических сооружений \n \n38 \n \n \nРисунок 3.38 – ПК 294+50. Крен городковых опор  \n3.1.4 Заключение по результатам визуального обследования \nПо результатам виз уального обследования состояние трубопроводов системы  \nвысоконапорного гидротранспорта  оценено как работоспособное техническое состояние : \nнекоторые из числа оцениваемых контролируемых параметров не отвечают требованиям \nпроекта или норм, но имеющиеся нарушен ия требований в конкретных условиях эксплуатации \nне приводят к нарушению работоспособности, и необходимая несущая способность конструкций \nи грунтов основания с учётом влияния имеющихся дефектов и повреждений обеспечивается. \nВыявлены следующие недочёты: \n– просадка лежневых опор с провисанием трубопроводов; \n– разрушение и крен городковых опор с провисанием трубопроводов;  \n– засыпка трубопроводов грунтом на пересечениях с насыпями автодорог и \nтехнологических проездов, что создает дополнительное сверхрасчётное защемление \nтруб;  \n– опирание трубопроводов непосредственно на грунт; \n– разрушение и просадка неподвижных опор. \nЛокальные недочеты  (дефекты), такие как наличие между трубами молодой поросли \nкустарника и деревьев в ближайшие годы на состоянии трубопроводов не повлияют. Нарушение \nтеплоизоляции также носит локальный характер и не снижает надежности  работы \nгидротранспорта, так как поврежденная теплоизоляция регулярно восстанавливается. \nВ момент обследования по трассе выполняются регулярные эксплуатационно-ремонтные \nработы, своевременно сть которых предотвращает внезапное разрушение трубопроводов и  \nпотерю устойчивости или опрокидывания их опор.  \nВыполняются следующие регулярные эксплуатационно-ремонтные работы: \n– замена труб; \n– замена и ремонт лежневых и городковых опор; \n– выправка трубопроводов подсыпкой балласта под опоры (суфляж); \n– очистка от растительности и планировка грунтом насыпи трассы трубопроводов;", "[стр. 40]\nОбследование гидротехнических сооружений \n \n39 \n \n– восстановление и замена теплоизоляции труб. \n3.2 Оценка соответствия критериям безопасности ГТС \nПри оценке соответствия критериям безопасности ГТС превышение выявлено только для \nтолщины стенок трубопроводов. В се остальные показатели находятся ниже к ритерия К1,  \nназначенного в Декларации безопасности ГТС [10]. \nКритерий первого уровня для толщины стенок трубопровода назначен равным исходной \n(заводской) толщине труб К1=10мм. Т.е. истирание труб по критериям безопасности \nнедопустимо, ч то является чр езмерно жёстким требованием. При последующем \nдекларировании критерий К1 рекомендуется пересмотреть.  \nБлизким к критерию первого уровня, кроме того, является также показатель №1.4 «Осадки \nопор, основания трубопровода (не равномерные, ведущие к провисанию, излому трубопровода): \nдля критерия первого уровня допускается просадка 3-х опор. \nПри эксплуатации ГТС и п ри осмотре трассы в рамках настоящего обследования \nзафиксированы просадки до 2-х опор подряд. На ПК52 вторая левая нитка трубопровода сошла \nболее, чем с трех опор. При этом при просадках лежневых опор и нарушении городковых опор \nтрубы местами опустились на грунт . Опирание труб на грунт не запрещено действующими \nкритериями безопасности ГТС, но не желательно т.к. ухудшает условия осмотра труб и замены \nих те плоизоляции. По данному показателю при последующем декларировании также \nрекомендуется выполнить уточнение  критериев, указав не только предельное количество \nпроседающих опор, но и суммарную длину допустимого свободного провиса трубопровода. \nДанный дополнительный показатель необходим, так как проектный шаг опор 4,0м сбивается на \nпереходах через водные объекты , что выз ывает двоякое толкование установленного в \nДекларации безопасности ГТС [10] критерия.  \nРасчёт допустимого свободного провиса трубопроводов, выполненный в рамках \nнастоящего обследования представлен ниже в подразделе 3.3.", "[стр. 41]\nОбследование гидротехнических сооружений \n \n40 \n \nТаблица 3.1 –Количественные диагностические показатели состояния системы \nвысоконапорного гидротранспорта и их критериальные значения", "[стр. 42]\nОбследование гидротехнических сооружений \n \n41 \n \nТаблица 3.2 –Качественные диагностические показатели состояния системы \nвысоконапорного гидротранспорта и их критериальные значения  \n \n3.3 Результаты поверочных расчётов \n3.3.1 Методика расчёта  \nМетодика проектирования и расчёта трубопроводов определяется следующей \nнормативной документацией: \n– ГОСТ 32388 -2013 Трубопроводы технологические. Нормы и методы расчёта на \nпрочность, вибрацию и сейсмические воздействия; \n– СП 33.13330.2012 Расчёт на прочность стальных трубопроводов. Актуализированная \nредакция СНиП 2.04.12-86; \n– СП 20.13330.2016 Нагрузки и воздействия;", "[стр. 43]\nОбследование гидротехнических сооружений \n \n42 \n \n– СП 37.13330.2012 Промышленный транспорт. Актуализированная редакция \nСНиП 2.05.07-91. \nВ рамках настоящего обследования в ыполнены поверочные расчёты трубопроводов на \nпрочность и жёсткость. \nУсилия от расчётных нагрузок и воздействий определены методами строительной \nмеханики путём расчёта статически неопределимых стержневых систем. Расчётная схема \nтрубопровода в общем случае выглядит следующим образом (Рисунок 3.39): \n \nРисунок 3.39 – Расчетная схема трубопровода  \nДля проверки трубопровода принимается расчетная схема с учетом возможной просадки \nлежневых опор и уменьшением сечения трубы до 5 мм, допускаемой «Правилами эксплуатации \nгидротехнических сооружений системы высоконапорного гидротранспорта Талнахской \nобогатительной фабрики» и критериями безопасности ГТС [10]. \n3.3.2 Исходные данные  \nИсходные данные для расчёта, взятые из справочных и нормативных  источников, \nпредставлены в табл. 3.3. \nТаблица 3.3 – Исходные данные для расчёта \n№ \nп/п Наименование Обозначение Ед. \nизм. Величина \n Информация о трубе \n1 Труба 273х10 \n2 Марка стали 09Г2С \n3 Модуль упругости E МПа 200000 \n4 Допускаемое напряжение [σq] МПа 180 \n Геометрические данные    \n5 Наружный диаметр трубы Da мм 273 \n6 Толщина стенки трубы s мм 10 \n7 Ослабленная толщина стенки трубы s мм 5 \n8 Толщина остеклования трубы  мм 3 \n9 Момент сопротивления трубы при толщине 10 мм W см3 524,11", "[стр. 44]\nОбследование гидротехнических сооружений \n \n43 \n \n№ \nп/п Наименование Обозначение Ед. \nизм. Величина \n10 Момент сопротивления трубы при толщине 5 мм W см3 276,98 \n11 Момент инерции сечения трубы при толщине 10 мм I см4 7154,09 \n12 Момент инерции сечения трубы при толщине 5 мм I см4 3780,81 \n Сведения о нагрузках    \n13 Плотность транспортируемой среды γср т/м3 1,2 \n14 Нормативная снеговая нагрузка qсн кН/м2 2,5 \n15 Погонный вес трубы  кг/м 64,86 \n16 Объёмный вес теплоизоляции трубы  кг/м3 60 \n17 Объёмный вес остеклования  т/м3 2,5 \n18 Коэффициент надёжности по нагрузке среды   1,0 \n19 Коэффициент надёжности по нагрузке, снег   1,4 \n20 Коэффициент надёжности по нагрузке, вес трубы   1,1 \n21 Коэффициент надёжности по нагрузке, изоляция   1,2 \n22 Коэффициент надёжности по нагрузке, остеклование   1,1 \n3.3.3 Расчёт трубы из условия на прочность \n \nРасстояние между отдельно стоящими опорами под трубопроводы должны назначаться, \nисходя из расчёта труб на прочность и жёсткость. \nСогласно ГОСТ 32388-2013 максимально допустимая длина пролёта lпр: \n   (1), \nгде W - момент инерции сечения трубы изгибу: \n,  \n[σq] - эффективное допускаемое напряжение от действия вертикальной нагрузки; согласно \nГОСТ 55596 -2013 допускаемое напряжение для стальных трубопроводов из стали \nмарки 09Г2С 180 МПа; \nq - погонный расчётный вес трубы с изоляцией, остеклованием, продуктом и снеговой \nнагрузкой; \nDа - наружный диаметр трубы трубопровода; \ns - номинальная толщина стенки трубы;", "[стр. 45]\nОбследование гидротехнических сооружений \n \n44 \n \nφbw - коэффициент прочности поперечного сварного шва, согласно табл. 5.2 \nГОСТ 32388˗2013, для труб равен 0,9. \nСогласно п.6.6 СП 33.13330.2012 нормативная нагрузка от веса транспортируемой среды \nна единицу длины трубопровода определяется по формуле: \n \nгде γср - плотность транспортируемой среды, по справочным данным плотность пульпы \nсоставляет 1,15-1,20 т/м3; \nde – наружный диаметр; \ntnom - номинальная толщина стенки трубы. \nСогласно п.6.8 СП 33.13330.2012 нормативная снеговая нагрузка qсн на единицу длины \nназемного трубопровода определяется по формуле: \n \nгде 0,4 – коэффициент перехода от веса снегового покрова земли к снеговой нагрузке на \nтрубопровод; \nSq - вес снегового покрова на 1 м2 горизонтальной поверхности земли 2,5 кН/м2  (согласно \nп.10.2 и приложению Е СП 20.13330.2016 Нагрузки и воздействия г. Норильск относится к V \nснеговому району). \nВес изоляционного покрытия определяется по формуле: \n, \nгде n - коэффициент надёжности по нагрузке (n = 1,2); \nγиз - удельный вес материала изоляции; \nDиз и Dн - соответственно диаметр изолированного трубопровода и его наружный диаметр. \nВес остеклования определяется по такой же формуле, как и теплоизоляции. \nТолщина остеклования – 3 мм, объёмный вес стекла 2,5т/м 3, коэффициент надёжности \nпо нагрузке для остеклования n = 1,1. \nСогласно формуле (1), при учёте всех вертикальных нагрузок с учётом коэффициентов \nнадёжности по нагрузке, из условия прочности трубы, для новой трубы с толщиной стенки 10мм \nполучается предельный пролёт равным: \nlпр = 23,91 м. \nПри условии возможного уменьшения толщины стенки трубы до 5 мм (согласно \n«Правилам эксплуатации гидротехнических сооружений системы высоконапорного \nгидротранспорта Талнахской обогатительной фабрики») предельный пролёт получается \nравным: \nlпр = 17,38 м. \n3.3.4 Расчёт трубы из условия на жёсткость \nРасчёт на жёсткость производится по формуле строительной механики (с некоторым \nзапасом, учитывая неразрезную конструкцию трубы): \n𝑓 = 5\n384 𝑞𝑙4\n𝐸𝐼        (2),", "[стр. 46]\nОбследование гидротехнических сооружений \n \n45 \n \nгде 𝑓 – прогиб трубы; \n𝑞 - общая нормативная вертикальная погонная нагрузка на трубу. \nВсе исходные данные для расчета даны в Таблица 3.3 \nПри толщине трубы в 10  мм и значении пролета между опорами для трубы диаметром \n273 мм равным 11,3 м (определяемое требованиями СП, ГОСТ и т.д. и приводимое в справочных \nданных), прогиб равен: \n𝑓 = 2,36 см. \nПри толщине трубы в 5 мм при таком же пролете: \nf = 4,48 см < 5 см \nНормативное значение прогиба согласно ГОСТ 32388-2013 составляет 0,02DN: \n0,02DN=0,02х250=50 мм=5 см, \nгде DN – условный проход трубопровода. \nДля оценки возможного прогиба трубопровода выполнен расчёт трубы при различных \nпролетах и толщинах, представленный в Таблица 3.4 \nТаблица 3.4 – Прогибы (см) в зависимости от пролёта (м) и толщины стенки \nтрубы (мм) \n№ Пролёт, Прогиб, см Примечание \n (расстояние между опорами для \nкоторого выполнен расчёт прогиба) п/п м Толщина 5 мм Толщина 10 мм \n1 4 0,07 0,04 Проектное расстояние между \nлежневыми опорами \n2 11,6 5,0 2,63 \nРасчётный предельный пролёт между \nопорами при нормативном прогибе 5см \nдля стенки t=5 мм \n3 13,6 9,40 5,0 \nРасчётный предельный пролёт между \nопорами при нормативном прогибе 5см \nдля стенки t=10 мм \n4 17,38 25,07 13,25 \nРасчётный предельный пролёт между \nопорами при предельной прочности \nтрубы со стенкой t=5 мм  \n5 23,91 89,8 47,46 \nРасчётный предельный пролёт между \nопорами при предельной прочности \nтрубы со стенкой t=10 мм \n3.3.5 Заключение по результатам расчётов \nАнализ результатов поверочных расчётов показывает следующее. \nУчитывая допустимое истирание трубы до толщины стенки 5,0 мм, предельное значение \nрасстояния между опорами по прогибу следует принять 11.6  м. Для новой трубы данное \nрасстояние, предельное по прогибу, достигает 13,6м.  \nУчитывая допустимое истирание трубы до толщины стенки 5,0 мм, предельное значение \nрасстояния между опорами по прочности следует принять 1 7,4 м. Для новой трубы данное \nрасстояние, предельное по про чности, достигает 23,9 м, что соответствует действующему \nкритерию К2 просадки 5 опор: (5+1)*4м=24м. \nВ итоге при последующем декларировании при уточнении критериев безопасности ГТС в \nкачестве критерия первого уровня для свободного провиса трубопровода рекомендуется \nпринять более жёсткий критерий К1=12 м, соответствующий просадке 2 опор . В качестве", "[стр. 47]\nОбследование гидротехнических сооружений \n \n46 \n \nкритерия второго уровня для свободного провиса трубопровода рекомендуется принять более \nжёсткий критерий: К2=16 м, соответствующий просадке 3 опор. \n3.4 Рассмотрение эксплуатационной документации \nПри анализе состояния ГТС рассмотрены следующие акты обследований, составленные \nв 2022г эксплуатационной службой Талнахской обогатительной фабрики: \n– Акт о выполненном предпаводковом обследовании ГТС системы высоконапорного \nгидротранспорта ТОФ от 20.05.2022, № ЗФ-71/032-акт. \n– Акт о выполненном обследовании технического состояния ГТС хвостохранилища \nТОФ от 10.06.2022, ЗФ-39-02-03/066-акт. \n– Акт о выполненно м послепаводковом обследовании ГТС системы высоконапорного \nгидротранспорта ТОФ от 17.06.2022, № ЗФ-71/045-акт. \n– Акт о выполненном обследовании технического состояния системы высоконапорного \nгидротранспорта ТОФ от 23.06.2022, ЗФ-39-02-03/76-акт. \nНаиболее пол но и подробно, в том числе с выявлением дефектов  и приложением \nфотоматериалов, обследование было произведено 06.06.2022  г. (Акт от 23.06.2022 ЗФ -02-\n03/076).  \nТаблица 3.5 – Дефекты по результатам визуальных наблюдений на участке НМЗ - \nПНС-1 – ПНС-2, обнаруженных комиссией ТОФ 06.06.2022 (Акт от 23.06.2022 ЗФ-02-\n03/076 «О выполнении технического состояния системы высоконапорного \nгидротранспорта ТОФ») \n \n№  \nп/п \nПикет \nНаименование дефекта \n1 ПК1-ПК6 просадка двух городковых опор под трубопроводом \n2 ПК7-10 прокладка трубопроводов по земле \n3 ПК12-25 складирование демонтированных фрагментов \nтеплоизоляции \n4 ПК32-33 трубопроводы не опираются на опоры, просадки \nотсутствуют \n5 ПК2-50 провисание трубопроводов на ПК10, ПК48, ПК49 \n6 ПК55-57 просадка железобетонного ростверка \n7 ПК60-63 провисание трубопровода по одной опоре \n8 ПК64-70  \nна ПК65 осадка городковой опоры под \nтрубопроводами \nна ПК69 имеются два трубопровода без опирания на \nопоры \n9 ПК81-90 зафиксировано провисание нитки № 4 по двум опорам \n10 ПК91-96 растительность между трубопроводами на ПК92 \n11 ПК102-103 \nпровисание трубопровода по одной опоре, \nна эстакадной части в районе р. Норильская имеются \nдеформации несущих конструкций", "[стр. 48]\nОбследование гидротехнических сооружений \n \n47 \n \n№  \nп/п \nПикет \nНаименование дефекта \n12 ПК104-108 имеется осадка ростверка опоры трубопроводов \n13 ПК109-111 \nтрещина на бетонном основании опоры на ПК110-111, \nосуществляется складирование демонтированных \nтруб \n14 ПК111-112 провисание трубопроводов по двум опорам \n15 ПК112-122 участок трубопроводов на ПК112-116 не опирается на \nопору, просадка отсутствует \n16 ПК125-144 имеется провисание трубопровода на ПК125-135 по \nдвум опорам \n17 ПК150-155 осадка ростверка опоры на ПК153 \n18 ПК164-170 просадка трубопровода по двум опорам \n ПК170-177 просадка трубопровода по одной опоре на ПК170-171", "[стр. 49]\nОбследование гидротехнических сооружений \n \n48 \n \n4 ЗАКЛЮЧЕНИЕ \nПри эксплуатации системы высоконапорного гидротранспорта  выявлены следующие \nнедочёты, подтверждённые в рамках настоящего обследования при осмотре трассы \nтрубопроводов: \n– просадка лежневых опор с провисанием трубопроводов; \n– разрушение и крен городковых опор с провисанием трубопроводов;  \n– засыпка трубопроводов грунтом на пересечениях с насыпями автодорог и \nтехнологических проездов, что создаёт дополнительное сверхрасчётное защемление \nтруб;  \n– опирание трубопроводов непосредственно на грунт; \n– разрушение и просадка неподвижных опор. \nВ момент обследования по трассе выполняются следующие регулярные \nэксплуатационно-ремонтные работы, своевременное выполнение которых исключает опасность \nвнезапного разрушения трубопроводов и потери устойчивости или опрокидывания их опор: \n– замена труб; \n– замена и ремонт лежневых и городковых опор; \n– выправка трубопроводов подсыпкой балласта под опоры (суфляж); \n– очистка от растительности и планировка грунтом насыпи трассы трубопроводов; \n– восстановление и замена теплоизоляции труб. \nПри оценке соответствия критериям безопасности ГТС превышение выявлено только для \nтолщины стенок трубопроводов. В се остальные показатели находятся ниже кр итерия К1,  \nназначенного в Декларации безопасности ГТС [10]. \nКритерий первого уровня для толщины стенок трубопровода назначен равным исходной \n(заводской) толщине труб : К1=10мм. Т.е. истирание труб по критериям безопаснос ти \nнедопустимо, что является чрезмерно жёстким требованием. При последующем \nдекларировании критерий К1 рекомендуется пересмотреть , уменьшив допустимую толщину \nстенки труб как минимум до К1=9мм (уточнить при назначении критериев). \nДополнительно при последую щем декларировании рекомендуется пересмотреть \nкритерий предельного количеств а проседающих опор, указав суммарную длину допустимого \nсвободного провиса трубопровода: К1=1 2м, К2=16м. Что позволит учесть допускаемое \nдействующими критериями снижение прочности труб при истирании их стенок до толщины 5 мм.  \nУчитывая, что в настоящее время некоторые из числа оцениваемых контролируемых \nпараметров не отвечает требованиям проекта или норм, но имеющиеся нарушения требований \nв конкретных условиях эксплуатации не приводят к нарушению работоспособности, и \nнеобходимая несущая способность конструкций и грунтов основания с учётом влияния \nимеющихся дефектов и повреждений обеспечивается , состояние труб опроводов системы  \nвысоконапорного гидротранспорта в итоге оценено как работоспособное техническое состояние. \nДополнительно для повышения надёжности и безотказности работы системы \nвысоконапорного гидротранспорта в первую очередь рекомендуется завершить замену и ремонт \nлежневых и городковых опор и выправку трубопроводов подсыпкой балласта под опоры. \nРекомендуемый срок выполнения ремонтных работ: \n– для свободных провисо в на длине 16  и более метров, что для проектных 4 -х \nметровых пролётов соответствует трём просевшим опорам подряд, при обнаружении", "[стр. 50]\nОбследование гидротехнических сооружений \n \n49 \n \nтаковых провисов, ремонт следует выполнять незамедлительно , в т.ч. и в зимний \nпериод года с установкой временных опор; \n– для свободных провисо в на длине 12 и менее  метров, что для проектных 4 -х \nметровых пролётов соответствует двум просевшим опорам подряд, ремонт \nрекомендуется выполнять при положительных температурах наружного воздуха \nпосле оттаивания грунтов основания, т.е. допускается перенос ремонта с зимнего на \nпоследующий летний период. \nПрочие менее срочные ремонтные работы, такие как суфляж, замена теплоизоляции, \nрасчистка осыпей на проходах под насыпями проездов и удаление растительности могут быть \nвыполнены, как это запланировано, в срок до последующего декларирования. ГОСТ 31937-2011", "[стр. 51]\nОбследование гидротехнических сооружений \n \n50 \n \nСПИСОК ЛИТЕРАТУРЫ \n1 Федеральный закон от 21.07.1997 № 117 -ФЗ (ред. от 11.06.2021) «О безопаснос ти \nгидротехнических сооружений» \n2 Федеральный закон от 30.12.2009 № 384 -ФЗ Технический регламент о безопасности \nзданий и сооружений» \n3 СП 58.13330.2019 «Гидротехнические сооружения. Основные положения» СНиП 33-01-\n2003 (с Изменением № 1) \n4 СП 25.13330.2020 Основания и фундаменты на вечномерзлых грунтах. \nСНиП 2.02.04˗88 (с Изменением № 1) \n5 СП 33.13330.2012 Расчет на прочность стальных трубопроводов. Актуализиро ванная \nредакция СНиП 2.04.12-86 (с Изменениями № 1, 2) \n6 СП 20.13330.2016 Нагрузки и воздействия . Актуализированная редакция \nСНиП 2.01.07˗85* (с Изменениями № 1, 2, 3, 4) \n7 СП 37.13330.2012 Промышленный транспорт. Актуализированная редакция \nСНиП 2.05.07-91* (с изменениями № 1, 2, 3, 4) \n8 ГОСТ 31937 -2011 «Здания и сооружения. Правила обследования и мониторинга \nтехнического состояния» \n9 Технические условия «Трубы, отводы, доборные элементы металлические с \nостеклованным покрытием» (ТУ 2851-253-95687873-2011). \n10 Декларация безопасности гидротехнических сооружений системы высоконапорного \nгидротранспорта Талнахской обогатительной фабрики ЗФ ПАЩ «ГМК «Норильский \nникель», 2021 г. \n11 Правила эксплуатации гидротехнических сооружений системы высоконапорного \nгидротранспорта Талнахской обогатительной фабрики, 2022 \n12 Проект мониторинга безопасности ГТС системы высоконапорного гидротранспорта \nТалнахской обогатительной фабрики ЗФ ПАО «ГМК «Норильский никель», 2022 \n13 Расчет вероятного вреда, который может быть причинён жизни, здоровью физических \nлиц, имуществу физических и юридических лиц в результате аварии гидротехнических \nсооружений, 2020 г. \n14 Акт регулярного обследования гидротехнического сооружения (за исключением \nсудоходных и портовых гидротехнических сооружений). Система высоконапорного \nгидротранспорта Талнахской обогатительной фабрики, 2021", "[стр. 52]\nПриложение А \nТехническое задание", "[стр. 53]\n", "[стр. 54]\n", "[стр. 55]\n", "[стр. 56]\nПриложение Б \nСхема системы высоконапорного гидротранспорта ТОФ-НМЗ"]};
